1	import Link from "next/link";
2	import { requireUser } from "@/lib/auth";
3	import { EmptyState } from "@/components/ui/primitives";
4	import type { MailFolder, MailboxInfo, ListResult } from "@/lib/mail/types";
5	import {
6	  listFolders,
7	  listMessages,
8	  getMailboxes,
9	} from "@/lib/actions-mail";
10	import { MailClient } from "@/components/customer/mail/MailClient";
11	
12	export const dynamic = "force-dynamic";
13	
14	export const metadata = { title: "Mail — Nxeon" };
15	
16	export default async function MailPage() {
17	  await requireUser();
18	
19	  let folders: MailFolder[] = [];
20	  let mailboxes: MailboxInfo[] = [];
21	  let list: ListResult = { messages: [], total: 0, page: 1, pageSize: 25 };
22	  let inboxPath = "INBOX";
23	  let failed = false;
24	
25	  try {
26	    const [f, mb] = await Promise.all([listFolders(), getMailboxes()]);
27	    folders = f;
28	    mailboxes = Array.isArray(mb) ? mb : mb ? [mb] : [];
29	    inboxPath = folders.find((x) => x.role === "inbox")?.path ?? folders[0]?.path ?? "INBOX";
30	    list = await listMessages(inboxPath, 1);
31	  } catch {
32	    failed = true;
33	  }
34	
35	  if (failed || folders.length === 0) {
36	    return (
37	      <div className="mx-auto max-w-2xl pt-10">
38	        <EmptyState
39	          title="No mailbox connected"
40	          sub="We couldn't reach a mailbox for your account. Set up business email on one of your domains to start using webmail here."
41	          action={
42	            <Link href="/dashboard/email" className="btn-primary">
43	              Set up email
44	            </Link>
45	          }
46	        />
47	      </div>
48	    );
49	  }
50	
51	  return (
52	    <MailClient
53	      initialFolders={folders}
54	      initialMailboxes={mailboxes}
55	      initialList={list}
56	      initialFolderPath={inboxPath}
57	    />
58	  );
59	}
