1	"use client";
2	
3	import { useCallback, useEffect, useRef, useState, useTransition } from "react";
4	import type {
5	  MailFolder,
6	  MailboxInfo,
7	  ListResult,
8	  MessageSummary,
9	  MessageFull,
10	  SendPayload,
11	} from "@/lib/mail/types";
12	import {
13	  listFolders,
14	  listMessages,
15	  getMessage,
16	  getMailboxes,
17	  sendMessage,
18	  setFlag,
19	  moveMessage,
20	  deleteMessage,
21	} from "@/lib/actions-mail";
22	import { FolderRail, type RailItem } from "./FolderRail";
23	import { MessageList } from "./MessageList";
24	import { ReadingPane } from "./ReadingPane";
25	import { ContactPanel } from "./ContactPanel";
26	import { Composer, type ComposeDraft } from "./Composer";
27	import { ShortcutHelp } from "./ShortcutHelp";
28	import { Icon, displayName, categoryOf, type MailTab } from "./util";
29	
30	const STARRED = "__starred__";
31	const SNOOZED = "__snoozed__";
32	
33	const ROLE_META: Record<string, { label: string; icon: RailItem["icon"]; order: number }> = {
34	  inbox: { label: "Inbox", icon: "inbox", order: 0 },
35	  sent: { label: "Sent", icon: "sent", order: 3 },
36	  drafts: { label: "Drafts", icon: "draft", order: 4 },
37	  junk: { label: "Spam", icon: "spam", order: 5 },
38	  trash: { label: "Trash", icon: "trash", order: 6 },
39	  archive: { label: "Archive", icon: "archive", order: 7 },
40	};
41	
42	export function MailClient({
43	  initialFolders,
44	  initialMailboxes,
45	  initialList,
46	  initialFolderPath,
47	}: {
48	  initialFolders: MailFolder[];
49	  initialMailboxes: MailboxInfo[];
50	  initialList: ListResult;
51	  initialFolderPath: string;
52	}) {
53	  const [folders, setFolders] = useState<MailFolder[]>(initialFolders);
54	  const [mailboxes, setMailboxes] = useState<MailboxInfo[]>(initialMailboxes);
55	  const [activeAddress, setActiveAddress] = useState<string | undefined>(initialMailboxes[0]?.address);
56	  const [selected, setSelected] = useState<string>(initialFolderPath);
57	  const [list, setList] = useState<ListResult>(initialList);
58	  const [page, setPage] = useState(1);
59	  const [tab, setTab] = useState<MailTab>("primary");
60	  const [search, setSearch] = useState("");
61	
62	  const [selectedUid, setSelectedUid] = useState<number | null>(null);
63	  const [cursorUid, setCursorUid] = useState<number | null>(null);
64	  const [message, setMessage] = useState<MessageFull | null>(null);
65	  const [msgLoading, setMsgLoading] = useState(false);
66	
67	  const [draft, setDraft] = useState<ComposeDraft | null>(null);
68	  const [mobilePane, setMobilePane] = useState<"list" | "read">("list");
69	  const [railOpen, setRailOpen] = useState(false);
70	  const [refreshing, setRefreshing] = useState(false);
71	  const [toast, setToast] = useState<string | null>(null);
72	  const [showHelp, setShowHelp] = useState(false);
73	
74	  const [listPending, startList] = useTransition();
75	  const searchTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
76	
77	  const mailbox = mailboxes.find((m) => m.address === activeAddress) ?? mailboxes[0] ?? null;
78	
79	  const inboxPath = folders.find((f) => f.role === "inbox")?.path ?? "INBOX";
80	  const archivePath = folders.find((f) => f.role === "archive")?.path;
81	  const trashPath = folders.find((f) => f.role === "trash")?.path;
82	
83	  /* ---- Rail model ------------------------------------------------------- */
84	  const byRole = (role: string) => folders.find((f) => f.role === role);
85	  const primaryItems: RailItem[] = [];
86	  const inbox = byRole("inbox");
87	  primaryItems.push({ key: inbox?.path ?? "INBOX", label: "Inbox", icon: "inbox", unread: inbox?.unread });
88	  primaryItems.push({ key: STARRED, label: "Starred", icon: "star", virtual: true });
89	  primaryItems.push({ key: SNOOZED, label: "Snoozed", icon: "clock", virtual: true });
90	  for (const role of ["sent", "drafts", "junk", "trash", "archive"] as const) {
91	    const f = byRole(role);
92	    const meta = ROLE_META[role];
93	    if (f) primaryItems.push({ key: f.path, label: meta.label, icon: meta.icon, unread: f.unread });
94	    else primaryItems.push({ key: `__missing_${role}`, label: meta.label, icon: meta.icon });
95	  }
96	  const customItems: RailItem[] = folders
97	    .filter((f) => f.role === "custom")
98	    .map((f) => ({ key: f.path, label: f.name, icon: "folder" as const, unread: f.unread }));
99	
100	  const labelFor = useCallback(
101	    (key: string): string => {
102	      if (key === STARRED) return "Starred";
103	      if (key === SNOOZED) return "Snoozed";
104	      const f = folders.find((x) => x.path === key);
105	      if (f) return ROLE_META[f.role]?.label ?? f.name;
106	      return "Mailbox";
107	    },
108	    [folders]
109	  );
110	
111	  const resolvePath = (key: string): string | null => {
112	    if (key === SNOOZED) return null;
113	    if (key === STARRED) return inboxPath;
114	    if (key.startsWith("__missing_")) return null;
115	    return key;
116	  };
117	
118	  /* ---- Loading ---------------------------------------------------------- */
119	  const loadList = useCallback(
120	    (key: string, pageNum: number, q: string, addr = activeAddress) => {
121	      const path = resolvePath(key);
122	      if (path === null) {
123	        setList({ messages: [], total: 0, page: 1, pageSize: initialList.pageSize });
124	        return;
125	      }
126	      startList(async () => {
127	        try {
128	          const res = await listMessages(path, pageNum, q || undefined, addr);
129	          if (key === STARRED) {
130	            const flagged = res.messages.filter((m) => m.flagged);
131	            setList({ messages: flagged, total: flagged.length, page: 1, pageSize: res.pageSize });
132	          } else {
133	            setList(res);
134	          }
135	        } catch {
136	          setToast("Couldn't load messages.");
137	        }
138	      });
139	    },
140	    [inboxPath, initialList.pageSize, activeAddress]
141	  );
142	
143	  const selectFolder = (key: string) => {
144	    setSelected(key);
145	    setPage(1);
146	    setRailOpen(false);
147	    setSelectedUid(null);
148	    setCursorUid(null);
149	    setMessage(null);
150	    setMobilePane("list");
151	    loadList(key, 1, search);
152	  };
153	
154	  /* ---- Mailbox switching ------------------------------------------------ */
155	  const switchMailbox = async (address: string) => {
156	    if (address === activeAddress) return;
157	    setActiveAddress(address);
158	    setSelectedUid(null);
159	    setCursorUid(null);
160	    setMessage(null);
161	    setMobilePane("list");
162	    setPage(1);
163	    setSearch("");
164	    setRailOpen(false);
165	    setRefreshing(true);
166	    try {
167	      const f = await listFolders(address);
168	      setFolders(f);
169	      const newInbox = f.find((x) => x.role === "inbox")?.path ?? f[0]?.path ?? "INBOX";
170	      setSelected(newInbox);
171	      loadList(newInbox, 1, "", address);
172	      // Refresh usage figures in the background — never block the switch on it.
173	      void getMailboxes()
174	        .then((mb) => setMailboxes(Array.isArray(mb) ? mb : mb ? [mb] : []))
175	        .catch(() => {});
176	    } catch {
177	      setToast("Couldn't switch mailbox.");
178	    } finally {
179	      setRefreshing(false);
180	    }
181	  };
182	
183	  const openMessage = (m: MessageSummary) => {
184	    setSelectedUid(m.uid);
185	    setCursorUid(m.uid);
186	    setMobilePane("read");
187	    setMsgLoading(true);
188	    // Optimistically mark as read.
189	    if (!m.seen) {
190	      setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (x.uid === m.uid ? { ...x, seen: true } : x)) }));
191	      setFolders((cur) => cur.map((f) => (f.path === m.folder ? { ...f, unread: Math.max(0, f.unread - 1) } : f)));
192	      void setFlag(m.folder, m.uid, "seen", true, activeAddress).catch(() => {});
193	    }
194	    (async () => {
195	      try {
196	        const full = await getMessage(m.folder, m.uid, activeAddress);
197	        setMessage(full);
198	      } catch {
199	        setToast("Couldn't open this message.");
200	        setMessage(null);
201	      } finally {
202	        setMsgLoading(false);
203	      }
204	    })();
205	  };
206	
207	  /* ---- Mutations -------------------------------------------------------- */
208	  const toggleStar = (m: MessageSummary | MessageFull) => {
209	    const next = !m.flagged;
210	    setList((cur) => ({ ...cur, messages: cur.messages.map((x) => (x.uid === m.uid ? { ...x, flagged: next } : x)) }));
211	    setMessage((cur) => (cur && cur.uid === m.uid ? { ...cur, flagged: next } : cur));
212	    if (selected === STARRED && !next) {
213	      // Un-starring inside the Starred view removes the row.
214	      setList((cur) => ({ ...cur, messages: cur.messages.filter((x) => x.uid !== m.uid), total: Math.max(0, cur.total - 1) }));
215	    }
216	    void setFlag(m.folder, m.uid, "flagged", next, activeAddress).catch(() => setToast("Couldn't update star."));
217	  };
218	
219	  const removeFromList = (m: MessageSummary | MessageFull) => {
220	    setList((cur) => ({ ...cur, messages: cur.messages.filter((x) => x.uid !== m.uid), total: Math.max(0, cur.total - 1) }));
221	    // Keep folder unread counts honest when an unread message leaves the folder.
222	    if (!m.seen) {
223	      setFolders((cur) => cur.map((f) => (f.path === m.folder ? { ...f, unread: Math.max(0, f.unread - 1) } : f)));
224	    }
225	    setSelectedUid(null);
226	    setCursorUid(null);
227	    setMessage(null);
228	    setMobilePane("list");
229	  };
230	
231	  const doArchive = () => {
232	    if (!message) return;
233	    const m = message;
234	    if (!archivePath || m.folder === archivePath) {
235	      setToast("No archive folder available.");
236	      return;
237	    }
238	    removeFromList(m);
239	    setToast("Message archived.");
240	    void moveMessage(m.folder, m.uid, archivePath, activeAddress).catch(() => setToast("Archive failed."));
241	  };
242	
243	  const doDelete = () => {
244	    if (!message) return;
245	    const m = message;
246	    removeFromList(m);
247	    // If already in trash, hard-delete; otherwise move to trash when possible.
248	    if (trashPath && m.folder !== trashPath) {
249	      setToast("Moved to Trash.");
250	      void moveMessage(m.folder, m.uid, trashPath, activeAddress).catch(() => setToast("Delete failed."));
251	    } else {
252	      setToast("Message deleted.");
253	      void deleteMessage(m.folder, m.uid, activeAddress).catch(() => setToast("Delete failed."));
254	    }
255	  };
256	
257	  const doMove = (toFolder: string) => {
258	    if (!message) return;
259	    const m = message;
260	    removeFromList(m);
261	    setToast(`Moved to ${labelFor(toFolder)}.`);
262	    void moveMessage(m.folder, m.uid, toFolder, activeAddress).catch(() => setToast("Move failed."));
263	  };
264	
265	  /* ---- Compose / reply -------------------------------------------------- */
266	  const stripRe = (s: string) => s.replace(/^\s*(re|fwd?):\s*/i, "").trim();
267	  const quoteOf = (m: MessageFull) =>
268	    m.html ??
269	    (m.text ? `<pre style="white-space:pre-wrap">${m.text.replace(/&/g, "&amp;").replace(/</g, "&lt;")}</pre>` : "");
270	
271	  const openCompose = (to = "") =>
272	    setDraft({ mode: "new", to, cc: "", subject: "", body: "" });
273	
274	  const openReply = (all: boolean) => {
275	    if (!message) return;
276	    const m = message;
277	    const selfAddr = mailbox?.address?.toLowerCase();
278	    const ccList = all
279	      ? [...m.to, ...m.cc].map((a) => a.address).filter((a) => a.toLowerCase() !== selfAddr && a.toLowerCase() !== m.from.address.toLowerCase())
280	      : [];
281	    setDraft({
282	      mode: all ? "replyAll" : "reply",
283	      to: m.from.address,
284	      cc: [...new Set(ccList)].join(", "),
285	      subject: `Re: ${stripRe(m.subject) || "(no subject)"}`,
286	      body: `\n\n`,
287	      quotedHtml: `<p>On ${new Date(m.date).toLocaleString()}, ${displayName(m.from)} wrote:</p>${quoteOf(m)}`,
288	      inReplyToUid: m.uid,
289	      replyFolder: m.folder,
290	    });
291	  };
292	
293	  const openForward = () => {
294	    if (!message) return;
295	    const m = message;
296	    setDraft({
297	      mode: "forward",
298	      to: "",
299	      cc: "",
300	      subject: `Fwd: ${stripRe(m.subject) || "(no subject)"}`,
301	      body: `\n\n`,
302	      quotedHtml: `<p>---------- Forwarded message ----------<br>From: ${displayName(m.from)} &lt;${m.from.address}&gt;<br>Date: ${new Date(m.date).toLocaleString()}<br>Subject: ${m.subject}</p>${quoteOf(m)}`,
303	    });
304	  };
305	
306	  const handleSend = async (payload: SendPayload) => {
307	    const res = await sendMessage(payload, activeAddress);
308	    if (res && res.ok === false) throw new Error(res.error || "The mail server rejected the message.");
309	    setToast("Message sent.");
310	    // If we're viewing Sent, refresh it.
311	    const sentPath = folders.find((f) => f.role === "sent")?.path;
312	    if (resolvePath(selected) === sentPath) loadList(selected, page, search);
313	  };
314	
315	  const quickReply = async (text: string) => {
316	    if (!message) return;
317	    const m = message;
318	    try {
319	      await handleSend({
320	        to: m.from.address,
321	        subject: `Re: ${stripRe(m.subject) || "(no subject)"}`,
322	        text,
323	        html: `<div style="white-space:pre-wrap">${text.replace(/&/g, "&amp;").replace(/</g, "&lt;")}</div>`,
324	        inReplyToUid: m.uid,
325	        replyFolder: m.folder,
326	      });
327	      setMessage((cur) => (cur ? { ...cur, answered: true } : cur));
328	    } catch (e) {
329	      setToast(e instanceof Error ? e.message : "Reply failed.");
330	      throw e;
331	    }
332	  };
333	
334	  /* ---- Search debounce -------------------------------------------------- */
335	  const onSearch = (s: string) => {
336	    setSearch(s);
337	    if (searchTimer.current) clearTimeout(searchTimer.current);
338	    searchTimer.current = setTimeout(() => {
339	      setPage(1);
340	      loadList(selected, 1, s);
341	    }, 350);
342	  };
343	
344	  const onPage = (p: number) => {
345	    setPage(p);
346	    loadList(selected, p, search);
347	  };
348	
349	  const onTab = (t: MailTab) => setTab(t);
350	
351	  const refresh = async () => {
352	    setRefreshing(true);
353	    try {
354	      const [f, mb] = await Promise.all([listFolders(activeAddress), getMailboxes()]);
355	      setFolders(f);
356	      setMailboxes(Array.isArray(mb) ? mb : mb ? [mb] : []);
357	      loadList(selected, page, search);
358	    } catch {
359	      setToast("Refresh failed.");
360	    } finally {
361	      setRefreshing(false);
362	    }
363	  };
364	
365	  /* ---- Toast auto-dismiss ---------------------------------------------- */
366	  useEffect(() => {
367	    if (!toast) return;
368	    const t = setTimeout(() => setToast(null), 2600);
369	    return () => clearTimeout(t);
370	  }, [toast]);
371	
372	  /* ---- Keyboard shortcuts ---------------------------------------------- */
373	  // Messages currently visible in the list (after the category-tab filter),
374	  // used to move the j/k selection cursor.
375	  const visibleMessages = list.messages.filter((m) => categoryOf(m.from, m.subject) === tab);
376	
377	  const scrollRowIntoView = (uid: number) => {
378	    requestAnimationFrame(() => {
379	      document.querySelector(`[data-mail-uid="${uid}"]`)?.scrollIntoView({ block: "nearest" });
380	    });
381	  };
382	
383	  const moveCursor = (dir: 1 | -1) => {
384	    if (visibleMessages.length === 0) return;
385	    const curId = cursorUid ?? selectedUid;
386	    let idx = visibleMessages.findIndex((m) => m.uid === curId);
387	    if (idx === -1) idx = dir === 1 ? -1 : 0;
388	    const next = Math.max(0, Math.min(visibleMessages.length - 1, idx + dir));
389	    const target = visibleMessages[next];
390	    if (target) {
391	      setCursorUid(target.uid);
392	      scrollRowIntoView(target.uid);
393	    }
394	  };
395	
396	  const openCursor = () => {
397	    const id = cursorUid ?? selectedUid;
398	    const m = visibleMessages.find((x) => x.uid === id);
399	    if (m) openMessage(m);
400	  };
401	
402	  // A single always-current handler behind a stable ref so the window listener
403	  // is bound once yet never reads stale state.
404	  const keyHandlerRef = useRef<(e: KeyboardEvent) => void>(() => {});
405	  keyHandlerRef.current = (e: KeyboardEvent) => {
406	    if (showHelp) {
407	      if (e.key === "Escape" || e.key === "?") {
408	        e.preventDefault();
409	        setShowHelp(false);
410	      }
411	      return;
412	    }
413	    // The Composer owns its own keys while it's open.
414	    if (draft) return;
415	
416	    const el = document.activeElement as HTMLElement | null;
417	    const typing =
418	      !!el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.tagName === "SELECT" || el.isContentEditable);
419	    if (typing) {
420	      if (e.key === "Escape") el?.blur();
421	      return;
422	    }
423	    if (e.metaKey || e.ctrlKey || e.altKey) return;
424	
425	    switch (e.key) {
426	      case "j": e.preventDefault(); moveCursor(1); break;
427	      case "k": e.preventDefault(); moveCursor(-1); break;
428	      case "Enter":
429	        // Let a focused button/link handle its own Enter instead of opening.
430	        if (el && (el.tagName === "BUTTON" || el.tagName === "A")) break;
431	        e.preventDefault();
432	        openCursor();
433	        break;
434	      case "o": e.preventDefault(); openCursor(); break;
435	      case "r": if (message) { e.preventDefault(); openReply(false); } break;
436	      case "a": if (message) { e.preventDefault(); openReply(true); } break;
437	      case "f": if (message) { e.preventDefault(); openForward(); } break;
438	      case "e": if (message) { e.preventDefault(); doArchive(); } break;
439	      case "#": if (message) { e.preventDefault(); doDelete(); } break;
440	      case "s": if (message) { e.preventDefault(); toggleStar(message); } break;
441	      case "c": e.preventDefault(); openCompose(); break;
442	      case "/": e.preventDefault(); document.getElementById("mail-search-input")?.focus(); break;
443	      case "?": e.preventDefault(); setShowHelp(true); break;
444	      case "Escape":
445	        e.preventDefault();
446	        setSelectedUid(null);
447	        setCursorUid(null);
448	        setMessage(null);
449	        setMobilePane("list");
450	        break;
451	      default: break;
452	    }
453	  };
454	
455	  useEffect(() => {
456	    const onKey = (e: KeyboardEvent) => keyHandlerRef.current(e);
457	    window.addEventListener("keydown", onKey);
458	    return () => window.removeEventListener("keydown", onKey);
459	  }, []);
460	
461	  /* ---- Render ----------------------------------------------------------- */
462	  return (
463	    <div className="relative flex h-[calc(100vh-8rem)] min-h-[560px] overflow-hidden rounded-2xl border border-white/[0.06] bg-navy-900/60 backdrop-blur-md" style={{ boxShadow: "0 8px 32px -12px rgb(0 0 0 / 0.5)" }}>
464	      {/* Folder rail — static on md+, slide-over on mobile */}
465	      <aside className="hidden w-56 flex-none border-r border-white/[0.06] bg-navy-950/30 md:flex lg:w-60">
466	        <FolderRail
467	          primary={primaryItems.filter((i) => !i.key.startsWith("__missing_"))}
468	          custom={customItems}
469	          selected={selected}
470	          mailbox={mailbox}
471	          mailboxes={mailboxes}
472	          activeAddress={activeAddress}
473	          onSwitchMailbox={switchMailbox}
474	          onSelect={selectFolder}
475	          onCompose={() => openCompose()}
476	          onRefresh={refresh}
477	          refreshing={refreshing}
478	        />
479	      </aside>
480	
481	      {/* Mobile rail drawer */}
482	      {railOpen && (
483	        <div className="absolute inset-0 z-40 md:hidden">
484	          <div className="absolute inset-0 bg-navy-950/70 backdrop-blur-sm" onClick={() => setRailOpen(false)} />
485	          <div className="absolute inset-y-0 left-0 w-64 border-r border-white/[0.06] bg-navy-900 shadow-2xl animate-fade-up">
486	            <FolderRail
487	              primary={primaryItems.filter((i) => !i.key.startsWith("__missing_"))}
488	              custom={customItems}
489	              selected={selected}
490	              mailbox={mailbox}
491	              mailboxes={mailboxes}
492	              activeAddress={activeAddress}
493	              onSwitchMailbox={switchMailbox}
494	              onSelect={selectFolder}
