229	/** Renders the email body. HTML is dropped into a fully sandboxed iframe (no
230	 *  allow-scripts, no allow-same-origin) so hostile markup/scripts cannot run or
231	 *  reach cookies/storage. Plaintext falls back to a pre block. */
232	function MessageBody({ html, text }: { html: string | null; text: string | null }) {
233	  const ref = useRef<HTMLIFrameElement>(null);
234	  const [height, setHeight] = useState(320);
235	
236	  const doc = html
237	    ? `<!doctype html><html><head><meta charset="utf-8"><base target="_blank"><meta name="color-scheme" content="light"><style>
238	        html,body{margin:0;padding:0;background:#ffffff;color:#1e293b;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:14px;line-height:1.6;word-break:break-word;overflow-wrap:anywhere;}
239	        body{padding:16px;}
240	        img{max-width:100%;height:auto;}
241	        a{color:#5f2ee8;}
242	        table{max-width:100%;}
243	        pre{white-space:pre-wrap;}
244	        blockquote{margin:0 0 0 12px;padding-left:12px;border-left:3px solid #e2e8f0;color:#64748b;}
245	      </style></head><body>${html}</body></html>`
246	    : null;
247	
248	  // Best-effort autosize: with sandbox="" we cannot read the inner document, so
249	  // grow to a comfortable default and let the iframe scroll for very tall mail.
250	  useEffect(() => {
251	    setHeight(html ? 480 : 0);
252	  }, [html]);
253	
254	  if (doc) {
255	    return (
256	      <iframe
257	        ref={ref}
258	        sandbox=""
259	        srcDoc={doc}
260	        title="Message content"
261	        className="w-full rounded-xl border border-white/[0.06] bg-white"
262	        style={{ height }}
263	      />
264	    );
265	  }
266	
267	  if (text && text.trim()) {
268	    return (
269	      <pre className="whitespace-pre-wrap break-words font-sans text-[14px] leading-relaxed text-slate-300">
270	        {text}
271	      </pre>
272	    );
273	  }
274	
275	  return <p className="text-sm italic text-slate-500">This message has no content.</p>;
276	}
