  // Flatten for the command palette: when a nav item has children, expose the
  // children (the real destinations) instead of the group header; flat items
  // (customer portal) pass through unchanged.
  const flatNav = nav.flatMap((s) =>
    s.items.flatMap((i) =>
      i.children && i.children.length > 0
        ? i.children.map((c) => ({ label: c.label, href: c.href, section: s.label }))
        : [{ label: i.label, href: i.href, section: s.label }]
    )
  );

