  // groupForPath() in lib/admin-groups.ts. The single winning href both
  // highlights its sub-link and expands its parent group. Bare "/admin" only
  // matches exactly so it never swallows deeper routes.
  let activeChildHref: string | null = null;
  {
    let bestLen = -1;
    for (const section of nav) {
      for (const item of section.items) {
