          const matches =
            c.href === pathname ||
            (c.href !== "/admin" && pathname.startsWith(c.href + "/"));
          if (matches && c.href.length > bestLen) {
            activeChildHref = c.href;
            bestLen = c.href.length;
          }
        }
      }
    }
  }

