77	  const diffDays = Math.round((startOfDay(now) - startOfDay(d)) / 86_400_000);
78	  if (diffDays <= 0) return "Today";
79	  if (diffDays === 1) return "Yesterday";
80	  if (diffDays < 7) return d.toLocaleDateString([], { weekday: "long" });
81	  const sameYear = d.getFullYear() === now.getFullYear();
82	  return d.toLocaleDateString([], sameYear ? { month: "long", day: "numeric" } : { month: "long", day: "numeric", year: "numeric" });
