/** Slim, icons-only version of the rail shown when collapsed. Keeps folder
 *  navigation and Compose reachable while giving the list + reading pane more
 *  room. */
export function MiniRail({
  items,
  selected,
  onSelect,
  onCompose,
  onExpand,
}: {
  items: RailItem[];
  selected: string;
  onSelect: (key: string) => void;
  onCompose: () => void;
  onExpand: () => void;
}) {
  return (
    <div className="flex h-full w-full flex-col items-center py-3">
      <button
        onClick={onExpand}
        title="Expand folders"
        aria-label="Expand folder rail"
        className="btn-ghost mb-2 rounded-lg p-2 text-slate-400 transition-colors hover:text-white"
      >
        <Icon.chevronRight size={17} />
      </button>
      <button
        onClick={onCompose}
        title="Compose"
        aria-label="Compose"
        className="mb-3 flex h-9 w-9 items-center justify-center rounded-xl bg-gradient-to-br from-accent-blue to-brand-500 text-white shadow-lg transition-transform hover:scale-105"
      >
        <Icon.compose size={16} />
      </button>
      <nav className="flex min-h-0 flex-1 flex-col items-center gap-1 overflow-y-auto">
        {items.map((it) => {
          const Ico = Icon[it.icon];
          const active = selected === it.key;
          return (
            <button
              key={it.key}
              onClick={() => onSelect(it.key)}
              title={it.label}
              aria-label={it.label}
              className={`relative flex h-9 w-9 flex-none items-center justify-center rounded-xl transition-colors ${
                active ? "nav-item-active text-white" : "text-slate-400 hover:bg-white/[0.05] hover:text-white"
              }`}
            >
              <Ico size={18} className={active ? "text-white" : ""} />
              {it.unread ? (
                <span className="absolute -right-0.5 -top-0.5 flex h-4 min-w-[16px] items-center justify-center rounded-full bg-brand-500 px-1 text-[9px] font-semibold text-white">
                  {it.unread > 99 ? "99+" : it.unread}
                </span>
              ) : null}
            </button>
          );
        })}
      </nav>
    </div>
  );
}

